142	/// Tooltip for a hovered closure.
143	fn closure_tooltip(leaf: &LinkedNode) -> Option<Tooltip> {
144	    // Only show this tooltip when hovering over the equals sign or arrow of
145	    // the closure. Showing it across the whole subtree is too noisy.
146	    if !matches!(leaf.kind(), SyntaxKind::Eq | SyntaxKind::Arrow) {
147	        return None;
148	    }
149	
150	    // Find the closure to analyze.
151	    let parent = leaf.parent()?;
152	    if parent.kind() != SyntaxKind::Closure {
153	        return None;
154	    }
155	
156	    // Analyze the closure's captures.
157	    let mut visitor = CapturesVisitor::new(None, Capturer::Function);
158	    visitor.visit(parent);
159	
160	    let captures = visitor.finish();
161	    let mut names: Vec<_> =
162	        captures.iter().map(|(name, ..)| eco_format!("`{name}`")).collect();
163	    if names.is_empty() {
164	        return None;
165	    }
166	
167	    names.sort();
168	
169	    let tooltip = repr::separated_list(&names, "and");
170	    Some(Tooltip::Text(eco_format!("This closure captures {tooltip}")))
171	}
172	
173	/// Tooltip text for a hovered length.
174	fn length_tooltip(length: Length) -> Option<Tooltip> {
175	    length.em.is_zero().then(|| {
176	        Tooltip::Code(eco_format!(
177	            "{}pt = {}mm = {}cm = {}in",
178	            round_with_precision(length.abs.to_pt(), 2),
179	            round_with_precision(length.abs.to_mm(), 2),
180	            round_with_precision(length.abs.to_cm(), 2),
181	            round_with_precision(length.abs.to_inches(), 2),
182	        ))
183	    })
184	}
