262	/// Tooltip for font.
263	fn font_tooltip(world: &dyn IdeWorld, leaf: &LinkedNode) -> Option<Tooltip> {
264	    // Ensure that we are on top of a string.
265	    if let Some(string) = leaf.cast::<ast::Str>()
266	        && let lower = string.get().to_lowercase()
267	
268	        // Ensure that we are in the arguments to the text function.
269	        && let Some(parent) = leaf.parent()
270	        && let Some(named) = parent.cast::<ast::Named>()
271	        && named.name().as_str() == "font"
272	
273	        // Find the font family.
274	        && let book = world.book()
275	        && let Some((_, iter)) = book
276	            .families()
277	            .find(|&(family, _)| family.to_lowercase().as_str() == lower.as_str())
278	    {
279	        let detail = summarize_font_family(iter.filter_map(|id| book.info(id)));
280	        return Some(Tooltip::Text(detail));
281	    }
282	
283	    None
284	}
