296	    type Response = Option<Tooltip>;
297	
298	    trait ResponseExt {
299	        /// Assert that there is no tooltip.
300	        fn must_be_none(&self) -> &Self;
301	        /// Assert that the tooltip equals the given message.
302	        fn must_be_text(&self, text: &str) -> &Self;
303	        /// Assert that the tooltip equals the given code.
304	        fn must_be_code(&self, code: &str) -> &Self;
305	    }
306	
307	    impl ResponseExt for Response {
308	        #[track_caller]
309	        fn must_be_none(&self) -> &Self {
310	            assert_eq!(*self, None);
311	            self
312	        }
313	
314	        #[track_caller]
315	        fn must_be_text(&self, text: &str) -> &Self {
316	            assert_eq!(*self, Some(Tooltip::Text(text.into())));
317	            self
318	        }
319	
320	        #[track_caller]
321	        fn must_be_code(&self, code: &str) -> &Self {
322	            assert_eq!(*self, Some(Tooltip::Code(code.into())));
323	            self
324	        }
325	    }
