433	    #[test]
434	    fn test_tooltip_math_function_call() {
435	        // Content plus parens
436	        test("$f(x)$", 1 /*f*/, Side::After).must_be_none();
437	        test("$f(x)$", 2 /*(*/, Side::After).must_be_none();
438	        test("$f(x)$", 3 /*x*/, Side::After).must_be_none();
439	        test("$sin()$", 1 /*s*/, Side::After)
440	            .must_be_code("op(text: [sin], limits: false)");
441	        // Actual function call + empty arg + trailing comma
442	        let vec_z = "vec(children: ([ℤ], []))";
443	        test("$vec(ZZ, ,)$", 1 /*v*/, Side::After).must_be_text("A column vector.");
444	        test("$vec(ZZ, ,)$", 4 /*(*/, Side::After).must_be_code(vec_z);
445	        test("$vec(ZZ, ,)$", 5 /*Z*/, Side::After).must_be_code("symbol(\"ℤ\")");
446	        test("$vec(ZZ, ,)$", 7 /*,*/, Side::After).must_be_code(vec_z);
447	        test("$vec(ZZ, ,)$", 8 /* */, Side::After).must_be_none();
448	        test("$vec(ZZ, ,)$", 9 /*,*/, Side::After).must_be_code(vec_z);
449	        test("$vec(ZZ, ,)$", 10 /*)*/, Side::After).must_be_code(vec_z);
450	        // Named args
451	        let vec_gap = "vec(gap: 0% + 1em, children: ())";
452	        test("$vec(gap:#1em)$", 5 /*g*/, Side::After)
453	            .must_be_text("The gap between elements.");
454	        test("$vec(gap:#1em)$", 8 /*:*/, Side::After).must_be_code(vec_gap);
455	        test("$vec(gap:#1em)$", 10 /*1*/, Side::After).must_be_none();
456	        // 2d args and spread args
457	        let mat = "mat(rows: (([1],), ([2],)))";
458	        test("$mat(1; ..#([2],))$", 1 /*m*/, Side::After).must_be_text("A matrix.");
459	        test("$mat(1; ..#([2],))$", 5 /*1*/, Side::After).must_be_none();
460	        test("$mat(1; ..#([2],))$", 6 /*;*/, Side::After).must_be_code(mat);
461	        test("$mat(1; ..#([2],))$", 8 /*.*/, Side::After).must_be_code(mat);
462	        test("$mat(1; ..#([2],))$", 10 /*#*/, Side::After).must_be_code(mat);
463	        test("$mat(1; ..#([2],))$", 11 /*(*/, Side::After).must_be_code("([2],)");
464	        // Symbol function and named arg
465	        test("$hat(i,size:#1em)$", 1, Side::After).must_be_code("symbol(\"^\")");
466	        test("$hat(i,size:#1em)$", 7, Side::After)
467	            .must_be_text("The size of the accent, relative to the width of the base.");
468	        // Field access call
469	        let box_desc = "An inline-level container that sizes content.";
470	        test("$std.box()$", 1 /*s*/, Side::After).must_be_code("<module global>");
471	        test("$std.box()$", 4 /*.*/, Side::After).must_be_text(box_desc);
472	        test("$std.box()$", 5 /*b*/, Side::After).must_be_text(box_desc);
473	        test("$std.box()$", 8 /*(*/, Side::After).must_be_code("box()");
474	    }
