481	    #[test]
482	    fn test_tooltip_closure() {
483	        test("#let f(x) = x + y", 11, Side::Before)
484	            .must_be_text("This closure captures `y`");
485	        // Same tooltip if `y` is defined first.
486	        test("#let y = 10; #let f(x) = x + y", 24, Side::Before)
487	            .must_be_text("This closure captures `y`");
488	        // Names are sorted.
489	        test("#let f(x) = x + y + z + a", 11, Side::Before)
490	            .must_be_text("This closure captures `a`, `y`, and `z`");
491	        // Names are de-duplicated.
492	        test("#let f(x) = x + y + z + y", 11, Side::Before)
493	            .must_be_text("This closure captures `y` and `z`");
494	        // With arrow syntax.
495	        test("#let f = (x) => x + y", 15, Side::Before)
496	            .must_be_text("This closure captures `y`");
497	        // No recursion with arrow syntax.
498	        test("#let f = (x) => x + y + f", 13, Side::After)
499	            .must_be_text("This closure captures `f` and `y`");
